repo <- "/home/user/WGBS-gigas-ploidy-desiccation"
lib <- read.csv(file.path(repo, "03_input_files/metadata/wgbs_libraries.csv"), stringsAsFactors = FALSE)
man <- read.csv(file.path(repo, "03_input_files/gannet_manifest.csv"), stringsAsFactors = FALSE)
ok <- function(label, cond) cat(sprintf("%-90s %s\n", label, if (isTRUE(cond)) "OK" else "*** FAIL ***"))
ok("22 rows, legacy_sample_index 1..22 in file order", nrow(lib) == 22 && identical(lib$legacy_sample_index, 1:22))
ok("every cov_file is in the manifest exactly once", all(vapply(lib$cov_file, function(f) sum(man$file == f) == 1, logical(1))))
ok("cov_file == <library_id>_R1.CpG_report.merged_CpG_evidence.cov", all(lib$cov_file == paste0(lib$library_id, "_R1.CpG_report.merged_CpG_evidence.cov")))
ok("zymo_project consistent with library_id", all(lib$zymo_project == sub("_.*", "", lib$library_id)))
ok("treatment == heat iff zr3534 iff cohort heat_experiment iff legacy_label ronit", all((lib$treatment == "heat") == (lib$zymo_project == "zr3534")) && all((lib$cohort == "heat_experiment") == (lib$zymo_project == "zr3534")) && all((lib$legacy_label == "ronit") == (lib$zymo_project == "zr3534")))
ok("design 5/5 heat, 6/6 control", identical(as.vector(table(lib$treatment, lib$ploidy)), c(6L, 5L, 6L, 5L)))
ok("animal_id prefix matches ploidy for zr3534", all(substr(lib$animal_id[lib$zymo_project == "zr3534"], 1, 1) == ifelse(lib$ploidy[lib$zymo_project == "zr3534"] == "diploid", "D", "T")))
ok("acute_heat_shock yes exactly for D19 D20 T19 T20", identical(sort(lib$animal_id[lib$acute_heat_shock == "yes"]), c("D19", "D20", "T19", "T20")))
sz <- file.size(file.path("/home/user/gannet_cache/cov_files", lib$cov_file))
ok("cache file sizes equal manifest bytes", all(sz == man$bytes[match(lib$cov_file, man$file)]))
md5 <- read.table("/home/user/gannet_cache/cov_md5.txt", stringsAsFactors = FALSE)
ok("cache md5 list equals manifest md5 (as recorded at download)", all(man$md5[match(lib$cov_file, man$file)] == md5$V1[match(lib$cov_file, basename(md5$V2))]))
